import unreal
TARGET='/Game/SSPR_Validation/NS_SSPR_ProjTest.NS_SSPR_ProjTest'
rows=[]
for comp in unreal.ObjectIterator(unreal.NiagaraComponent):
    try:
        asset=comp.get_asset()
        if asset and asset.get_path_name()==TARGET:
            owner=comp.get_owner()
            row={'component':comp.get_path_name(),'owner':owner.get_path_name() if owner else None,'active':bool(comp.is_active()),'tickEnabled':bool(comp.is_component_tick_enabled()),'visible':bool(comp.is_visible()),'asset':asset.get_path_name()}
            for method in ['get_num_active_particles','get_approx_memory_usage']:
                if hasattr(comp,method):
                    try: row[method]=getattr(comp,method)()
                    except Exception as e: row[method]='ERR:'+str(e)
            rows.append(row)
    except Exception:
        pass
print('COMPONENTS=' + repr(rows))
print('DIAGNOSTIC_METHODS=' + repr([n for n in dir(unreal.NiagaraComponent) if any(k in n.lower() for k in ['particle','count','simulation','tick','system_instance'])]))
